-- Safe to re-run: existing pubs and drinks are left alone.
begin;















-- One seed entry per drink in the price history, so trends start from the seed price.
select d.pub_id, d.id, d.name, d.category, d.measure, d.current_price, d.last_updated_at, 'seed'
from public.drinks d
where d.source = 'seed' and not exists (select 1 from public.price_reports r where r.drink_id = d.id);

commit;
